-- 5,000 real Spotify track metadata records from the user-uploaded spotify_songs.csv (TidyTuesday 2020).
-- Artist/album/track names and durations sourced from CSV; names truncated to 40 chars to fit existing schema.
-- monthly_listener numbers are SYNTHETIC TEST VALUES, NOT real Spotify listener statistics.
-- Album duration sums only selected tracks, not necessarily entire album.
-- Feature_Artist derived conservatively from explicit feat./ft./with text in full CSV track titles.
-- Import into EMPTY Artist, Album, Song and Feature_Artist tables.
-- IDs are explicitly assigned starting at 1.
-- Uses the correct Artist column name: `artist_name`.
-- CAUTION: Review truncation for possible collisions of long names.
START TRANSACTION;

